-- Fakt kartochkalari orqa tomonining ruscha matni — 73-partiya:
-- Qozizoda Rumiy, Sadriddin Ayniy, Said Ahmad.

UPDATE fact_cards SET detail_ru = 'В статье Люсьена Керена на Ziyouz.com сказано, что Казизаде Руми родился в 1337 году в турецком городе Бурсе. Позже в поисках знания он взял путь на Мавераннахр и Хорасан. Источник: Ziyouz.com, статья «Астрономическая школа Мирзо Улугбека» (Люсьен Керен).' WHERE id = 2274;
UPDATE fact_cards SET detail_ru = 'Первые уроки Казизаде Руми получил у энциклопедического учёного Шамсиддина аль-Фанари. Аль-Фанари помог ему тайно покинуть Турцию и глубоко изучить астрономию и математику в известных медресе Мавераннахра и Хорасана. Источник: Ziyouz.com, статья «Астрономическая школа Мирзо Улугбека» (Люсьен Керен).' WHERE id = 2275;
UPDATE fact_cards SET detail_ru = 'Казизаде Руми был одним из самых почитаемых учёных в астрономии и математике в самаркандском медресе. Заметив в Улугбеке редкое дарование, он направил его к глубокому изучению астрономии; Улугбек многому у него научился и считал его своим наставником. Источник: Ziyouz.com, статья «Астрономическая школа Мирзо Улугбека» (Люсьен Керен).' WHERE id = 2276;
UPDATE fact_cards SET detail_ru = 'В энциклопедической статье о Мирзо Улугбеке на Ziyouz.com Казизаде Руми назван «Платоном своего времени», и сказано, что Улугбек считал его своим наставником. Это показывает его высокий научный вес. Источник: Ziyouz.com, статья «Мирзо Улугбек (1394–1449)».' WHERE id = 2277;
UPDATE fact_cards SET detail_ru = 'В статье профессора М. Мамадазимова, со ссылкой на сочинение Салиха Заки «Асар аль-Бакия», говорится, что Улугбек назначил ведущими людьми в построенной в 1420 году обсерватории Гиясиддина Джамшида (Каши) и Казизаде Руми. Они были опорами самаркандской научной школы. Источник: Ziyouz.com, статья «Мирзо Улугбек и его академия» (М. Мамадазимов, газета «Маърифат»).' WHERE id = 2278;
UPDATE fact_cards SET detail_ru = 'По статье Люсьена Керена, в 1420 году строительные работы в медресе на площади Регистан были завершены, и Казизаде Руми дал первый урок в присутствии Улугбека. Новое медресе стало самым известным в своё время. Источник: Ziyouz.com, статья «Астрономическая школа Мирзо Улугбека» (Люсьен Керен).' WHERE id = 2279;
UPDATE fact_cards SET detail_ru = 'В предисловии к «Зиджу Гурагани» сказано, что наблюдения светил велись совместно Казизаде Руми и Гиясиддином Джамшидом; в начале работы умер Гиясиддин, позже — Казизаде Руми, а затем сочинение завершил Али Кушчи. Источник: Ziyouz.com, статьи «Мирзо Улугбек и его академия» (М. Мамадазимов) и «Астрономическая школа Мирзо Улугбека» (Люсьен Керен).' WHERE id = 2280;
UPDATE fact_cards SET detail_ru = 'По источнику, смерть Казизаде Руми в 1436 году стала для учёных большой утратой — в ту пору работа по составлению звёздной таблицы ещё шла. Позже Улугбек во вступительной части «Зиджа» выразил глубокое почтение своим наставникам. Источник: Ziyouz.com, статья «Астрономическая школа Мирзо Улугбека» (Люсьен Керен).' WHERE id = 2281;

UPDATE fact_cards SET detail_ru = 'Садриддин Айни родился в 1878 году в Гиждуванском районе Бухарской области. Настоящее его имя — Садриддин Саидмурадзаде, а «Айни» — литературный псевдоним. Источник: Ziyouz.com, раздел «Узбекская проза».' WHERE id = 2282;
UPDATE fact_cards SET detail_ru = 'В 1884–1887 годах Айни учился в школе старого образца. Затем он получал образование в бухарских медресе Мир-Араб, Алим-хана, Бадалбека, Хаджи Захида и Кукельдаш. Источник: Ziyouz.com, раздел «Узбекская проза».' WHERE id = 2283;
UPDATE fact_cards SET detail_ru = 'Айни открывал в Бухаре школы нового метода, создавал для них учебные пособия и в 1909 году составил учебник «Воспитание молодёжи». Он деятельно участвовал в движении младобухарцев, а на его взгляды повлияли Ахмад Дониш и джадидские просветители. Источник: Ziyouz.com, раздел «Узбекская проза».' WHERE id = 2284;
UPDATE fact_cards SET detail_ru = 'Айни творил на узбекском и таджикском языках: роман «Дохунда» написан на таджикском (1927–1929), роман «Рабы» — на узбекском (1934). Его сочинения «Дохунда», «Рабы», «Смерть ростовщика» и «Воспоминания» переведены на иностранные языки. Источник: Ziyouz.com, раздел «Узбекская проза».' WHERE id = 2285;
UPDATE fact_cards SET detail_ru = 'Роман «Рабы» написан в 1934 году на узбекском языке. Перу Айни принадлежат и повести «Бухарские палачи» (1922), «Старая школа» (1935) и сатирическая «Смерть ростовщика» (1939). Источник: Ziyouz.com, раздел «Узбекская проза».' WHERE id = 2286;
UPDATE fact_cards SET detail_ru = '«Воспоминания» (1949–1954) состоят из четырёх частей, и в них отражена прошлая жизнь Бухары. Это сочинение переведено и на иностранные языки. Источник: Ziyouz.com, раздел «Узбекская проза».' WHERE id = 2287;
UPDATE fact_cards SET detail_ru = 'Айни создал исследования о Фирдоуси, Рудаки, Саади и Алишере Навои и дал сведения более чем о двухстах сочинителях тысячелетней истории таджикской и узбекской словесности. Он был доктором филологических наук (1948), профессором (1950), а с 1943 года — почётным членом Академии наук Узбекистана. Источник: Ziyouz.com, раздел «Узбекская проза».' WHERE id = 2288;
UPDATE fact_cards SET detail_ru = 'Садриддин Айни умер в 1954 году. В 1951–1954 годах он был первым президентом Академии наук Таджикистана, а в 1967 году в Самарканде был открыт его мемориальный дом-музей. Источник: Ziyouz.com, раздел «Узбекская проза».' WHERE id = 2289;

UPDATE fact_cards SET detail_ru = 'Саид Ахмад родился 10 июня 1920 года в Ташкенте. Настоящее его имя — Хусанходжаев Саидахмад, а «Саид Ахмад» — литературный псевдоним. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2068;
UPDATE fact_cards SET detail_ru = 'Саид Ахмад учился в Ташкентском художественном училище, а в 1940–1943 годах — в Ташкентском педагогическом институте. Первый его сборник рассказов «Подарок» был издан в 1940 году; он работал литературным сотрудником в журнале «Муштум» и в газете «Ёш ленинчи». Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2069;
UPDATE fact_cards SET detail_ru = 'Трилогия «Горизонт» — вершина творчества Саида Ахмада, создана она в 1964–1974 годах. В 1988 году был издан и роман писателя «Тишина». Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2070;
UPDATE fact_cards SET detail_ru = 'Комедия «Бунт невесток» написана в 1976 году. В 1986 году Саид Ахмад создал и комедию «Зять»; сатирические и юмористические рассказы занимают в его творчестве весомое место. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2071;
UPDATE fact_cards SET detail_ru = 'В 1947 году Саид Ахмад был арестован по обвинению во «враге народа». После смерти Сталина он был оправдан и продолжил творчество. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2072;
UPDATE fact_cards SET detail_ru = 'Женой Саида Ахмада была поэтесса Саида Зуннунова. Она родилась в 1926 году в городе Андижане и была автором таких сочинений, как «Ваша дочь написала» (1948), «Долина цветов» (1954), «Гулхан» (1959). Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели»: Саида Зуннунова.' WHERE id = 2073;
UPDATE fact_cards SET detail_ru = 'Саид Ахмад был удостоен в 1980 году звания народного писателя Узбекистана, а в 1999-м — звания «Герой Узбекистана». Он награждён орденами «Дустлик» (1996) и «За великие заслуги» (1997). Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2074;
UPDATE fact_cards SET detail_ru = 'Саид Ахмад умер в 2007 году. В последние годы жизни он создал книги «Черноглазый безумец» (2001) и «Рассвет, оставшийся на ресницах» (2003). Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2075;
